    public static function verificarUrl(string $rota): string
    {
        $paginaAtual = trim($_SERVER['REQUEST_URI'], '/');

        return str_contains($paginaAtual, $rota) ? 'active' : '';
    }

    public static function getDadosMenu($paginaAtual)
    {
        $menuInfo = [
            'titulo' => 'Area de Trabalho',
            'svg' => self::icone('areaTrabalho')
        ];

        if (str_contains($paginaAtual, 'parceiros/index')) {

            $menuInfo['titulo'] = 'Parceiros';
            $menuInfo['svg'] = self::icone('parceiros');
        } elseif (str_contains($paginaAtual, 'mentores/index')) {

            $menuInfo['titulo'] = 'Mentores';
            $menuInfo['svg'] = self::icone('mentores');
        } elseif (str_contains($paginaAtual, 'equipe/index')) {

            $menuInfo['titulo'] = 'Equipe';
            $menuInfo['svg'] = self::icone('equipe');
        } elseif (str_contains($paginaAtual, 'startups/index')) {

            $menuInfo['titulo'] = 'Startups';
            $menuInfo['svg'] = self::icone('startups');
        }

        return $menuInfo;
    }

    public static function buscarNotificacoes(): array
    {
        $usuarioId = auth::id();

        if ($usuarioId === '') {
            return [];
        }

        return notificacao::buscarPorUsuario($usuarioId);
    }

    public static function buscarUsuarioLogado(): ?array
    {
        $usuarioId = auth::id();

        if ($usuarioId === null) {
            return null;
        }

        $stmt = parent::pegarBanco()->prepare('SELECT nome, email FROM usuario WHERE id = :id LIMIT 1');
        $stmt->execute(['id' => $usuarioId]);

        return $stmt->fetch(\PDO::FETCH_ASSOC) ?: null;
    }

    // provisório vibe codada ela só reseta a visualizada de 1 pra = 0
    public static function resetarVisualizacao(): void
    {
        $usuarioId = auth::id();

        if ($usuarioId === null || $usuarioId === '') {
            return;
        }

        notificacao::resetarVisualizacao((int) $usuarioId);
    }
}
